and-umpire-services/historic-home-claim-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Insurance Estimate Review","url":"https://virginiainsuranceappraiser.com/appraisal-and-umpire-services/carrier-estimate-review/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Umpire Selection & Services","url":"https://virginiainsuranceappraiser.com/appraisal-and-umpire-services/umpire-selection-and-services/"}}]},"openingHoursSpecification":[{"@type":"OpeningHoursSpecification","dayOfWeek":["Monday","Tuesday","Wednesday","Thursday","Friday"],"opens":"08:00","closes":"18:00"}]},{"@type":"WebSite","@id":"https://virginiainsuranceappraiser.com/#website","url":"https://virginiainsuranceappraiser.com/","name":"Virginia Insurance Appraiser","publisher":{"@id":"https://virginiainsuranceappraiser.com/#business"},"inLanguage":"en-US"},{"@type":"WebPage","@id":"https://virginiainsuranceappraiser.com/claim-and-policy-terms/#webpage","url":"https://virginiainsuranceappraiser.com/claim-and-policy-terms/","name":"Insurance Claim Glossary | 40+ Policy Terms Defined","description":"Insurance claim glossary of 40+ policy and appraisal terms in plain English: ACV, RCV, umpire, VPIA, hurricane deductible and more.","inLanguage":"en-US","isPartOf":{"@id":"https://virginiainsuranceappraiser.com/#website"},"about":{"@id":"https://virginiainsuranceappraiser.com/#business"},"publisher":{"@id":"https://virginiainsuranceappraiser.com/#business"},"dateModified":"2026-11-14","breadcrumb":{"@id":"https://virginiainsuranceappraiser.com/claim-and-policy-terms/#breadcrumb"},"primaryImageOfPage":{"@id":"https://virginiainsuranceappraiser.com/claim-and-policy-terms/#primaryimage"},"mainEntity":{"@id":"https://virginiainsuranceappraiser.com/claim-and-policy-terms/#definedtermset"}},{"@type":"ImageObject","@id":"https://virginiainsuranceappraiser.com/claim-and-policy-terms/#primaryimage","url":"https://virginiainsuranceappraiser.com/assets/img/photos/laptop-estimate.webp","width":1024,"height":626,"caption":"Overhead view of hands typing on a laptop showing a spreadsheet on a wooden desk beside a notebook, sunglasses and a cup of coffee."},{"@type":"DefinedTermSet","name":"Insurance claim and policy terms","hasDefinedTerm":[{"@type":"DefinedTerm","name":"Actual cash value (ACV)","description":"Replacement cost minus depreciation. Many policies pay ACV first and the rest after repairs.","inDefinedTermSet":{"@id":"https://virginiainsuranceappraiser.com/claim-and-policy-terms/#definedtermset"}},{"@type":"DefinedTerm","name":"Additional living expense (ALE)","description":"Coverage for the extra cost of living elsewhere while a home is being repaired after a covered loss.","inDefinedTermSet":{"@id":"https://virginiainsuranceappraiser.com/claim-and-policy-terms/#definedtermset"}},{"@type":"DefinedTerm","name":"Amount of loss","description":"The dollar value of a covered loss. It’s the only question an appraisal panel decides.","inDefinedTermSet":{"@id":"https://virginiainsuranceappraiser.com/claim-and-policy-terms/#definedtermset"}},{"@type":"DefinedTerm","name":"Appraisal award","description":"The written decision signed by two of the three panel members that sets the amount of loss.","inDefinedTermSet":{"@id":"https://virginiainsuranceappraiser.com/claim-and-policy-terms/#definedtermset"}},{"@type":"DefinedTerm","name":"Appraisal clause","description":"The policy condition that lets either party demand appraisal when they disagree on the amount of loss.","inDefinedTermSet":{"@id":"https://virginiainsuranceappraiser.com/claim-and-policy-terms/#definedtermset"}},{"@type":"DefinedTerm","name":"Appraiser","description":"The person each side names to value the loss during appraisal. Usually required to be competent and disinterested.","inDefinedTermSet":{"@id":"https://virginiainsuranceappraiser.com/claim-and-policy-terms/#definedtermset"}},{"@type":"DefinedTerm","name":"Bureau of Insurance","description":"The division of Virginia’s State Corporation Commission that regulates insurers, agents and public adjusters.","inDefinedTermSet":{"@id":"https://virginiainsuranceappraiser.com/claim-and-policy-terms/#definedtermset"}},{"@type":"DefinedTerm","name":"Coinsurance","description":"A commercial policy clause that reduces payment if a building was insured for less than a set percentage of its value.","inDefinedTermSet":{"@id":"https://virginiainsuranceappraiser.com/claim-and-policy-terms/#definedtermset"}},{"@type":"DefinedTerm","name":"Collateral damage","description":"Damage to soft metals, screens or other items that helps confirm a storm’s date and severity.","inDefinedTermSet":{"@id":"https://virginiainsuranceappraiser.com/claim-and-policy-terms/#definedtermset"}},{"@type":"DefinedTerm","name":"Coverage A","description":"Dwelling coverage on a homeowners policy: the house and attached structures.","inDefinedTermSet":{"@id":"https://virginiainsuranceappraiser.com/claim-and-policy-terms/#definedtermset"}},{"@type":"DefinedTerm","name":"Coverage B","description":"Other structures coverage, such as detached garages, sheds and fences.","inDefinedTermSet":{"@id":"https://virginiainsuranceappraiser.com/claim-and-policy-terms/#definedtermset"}},{"@type":"DefinedTerm","name":"Coverage C","description":"Personal property coverage for contents.","inDefinedTermSet":{"@id":"https://virginiainsuranceappraiser.com/claim-and-policy-terms/#definedtermset"}},{"@type":"DefinedTerm","name":"Debris removal","description":"Coverage for removing debris after a covered loss. Tree removal often has separate, lower limits.","inDefinedTermSet":{"@id":"https://virginiainsuranceappraiser.com/claim-and-policy-terms/#definedtermset"}},{"@type":"DefinedTerm","name":"Declarations page","description":"The summary page of a policy listing the insured, limits, deductibles and endorsements.","inDefinedTermSet":{"@id":"https://virginiainsuranceappraiser.com/claim-and-policy-terms/#definedtermset"}},{"@type":"DefinedTerm","name":"Deductible","description":"The share of a covered loss the policyholder pays before the insurer pays.","inDefinedTermSet":{"@id":"https://virginiainsuranceappraiser.com/claim-and-policy-terms/#definedtermset"}},{"@type":"DefinedTerm","name":"Depreciation","description":"The reduction in value from age, wear and obsolescence used to calculate actual cash value.","inDefinedTermSet":{"@id":"https://virginiainsuranceappraiser.com/claim-and-policy-terms/#definedtermset"}},{"@type":"DefinedTerm","name":"Derecho","description":"A long-lived, widespread windstorm from a line of thunderstorms, such as the June 2012 storm across Virginia.","inDefinedTermSet":{"@id":"https://virginiainsuranceappraiser.com/claim-and-policy-terms/#definedtermset"}},{"@type":"DefinedTerm","name":"Disinterested","description":"Having no financial stake in a claim’s outcome. Many appraisal clauses require it of each appraiser.","inDefinedTermSet":{"@id":"https://virginiainsuranceappraiser.com/claim-and-policy-terms/#definedtermset"}},{"@type":"DefinedTerm","name":"Endorsement","description":"A form that adds to, removes or changes the terms of the base policy.","inDefinedTermSet":{"@id":"https://virginiainsuranceappraiser.com/claim-and-policy-terms/#definedtermset"}},{"@type":"DefinedTerm","name":"Estimate review","description":"An independent, line-by-line check of an insurer’s estimate against the damage and local pricing.","inDefinedTermSet":{"@id":"https://virginiainsuranceappraiser.com/claim-and-policy-terms/#definedtermset"}},{"@type":"DefinedTerm","name":"FAIR Plan","description":"A state insurance pool for owners who can’t find coverage elsewhere. Virginia’s is the VPIA.","inDefinedTermSet":{"@id":"https://virginiainsuranceappraiser.com/claim-and-policy-terms/#definedtermset"}},{"@type":"DefinedTerm","name":"Functional damage","description":"Damage that affects how a material performs, such as water-shedding or service life, as opposed to cosmetic damage.","inDefinedTermSet":{"@id":"https://virginiainsuranceappraiser.com/claim-and-policy-terms/#definedtermset"}},{"@type":"DefinedTerm","name":"Hurricane deductible","description":"A separate deductible, often a percentage of Coverage A, that applies to losses from a hurricane or named storm.","inDefinedTermSet":{"@id":"https://virginiainsuranceappraiser.com/claim-and-policy-terms/#definedtermset"}},{"@type":"DefinedTerm","name":"Like kind and quality","description":"The standard for replacement materials: comparable in type and quality, not necessarily identical.","inDefinedTermSet":{"@id":"https://virginiainsuranceappraiser.com/claim-and-policy-terms/#definedtermset"}},{"@type":"DefinedTerm","name":"Line item","description":"A single priced entry in an estimate, such as a quantity of shingles or a room of drywall.","inDefinedTermSet":{"@id":"https://virginiainsuranceappraiser.com/claim-and-policy-terms/#definedtermset"}},{"@type":"DefinedTerm","name":"Matching","description":"Whether new materials can reasonably match undamaged materials, a common dispute after partial damage.","inDefinedTermSet":{"@id":"https://virginiainsuranceappraiser.com/claim-and-policy-terms/#definedtermset"}},{"@type":"DefinedTerm","name":"Mitigation","description":"Steps to prevent further damage after a loss, such as tarping or water extraction. Usually required and reimbursable.","inDefinedTermSet":{"@id":"https://virginiainsuranceappraiser.com/claim-and-policy-terms/#definedtermset"}},{"@type":"DefinedTerm","name":"Named storm","description":"A tropical storm or hurricane named by the National Hurricane Center. Often the trigger for a separate deductible.","inDefinedTermSet":{"@id":"https://virginiainsuranceappraiser.com/claim-and-policy-terms/#definedtermset"}},{"@type":"DefinedTerm","name":"Ordinance or law coverage","description":"Coverage for added costs of meeting building codes or local rules during repair, usually with its own limit.","inDefinedTermSet":{"@id":"https://virginiainsuranceappraiser.com/claim-and-policy-terms/#definedtermset"}},{"@type":"DefinedTerm","name":"Overhead and profit (O&P)","description":"A general contractor’s markup for coordinating multiple trades, often 10% and 10%.","inDefinedTermSet":{"@id":"https://virginiainsuranceappraiser.com/claim-and-policy-terms/#definedtermset"}},{"@type":"DefinedTerm","name":"Proof of loss","description":"A sworn statement of the amount claimed. Many policies require it within a set time after the insurer requests it.","inDefinedTermSet":{"@id":"https://virginiainsuranceappraiser.com/claim-and-policy-terms/#definedtermset"}},{"@type":"DefinedTerm","name":"Public adjuster","description":"A professional licensed by the Bureau of Insurance to handle and negotiate a claim for the policyholder for a fee.","inDefinedTermSet":{"@id":"https://virginiainsuranceappraiser.com/claim-and-policy-terms/#definedtermset"}},{"@type":"DefinedTerm","name":"Recoverable depreciation","description":"Depreciation held back from the first payment and paid once repairs are completed.","inDefinedTermSet":{"@id":"https://virginiainsuranceappraiser.com/claim-and-policy-terms/#definedtermset"}},{"@type":"DefinedTerm","name":"Replacement cost value (RCV)","description":"The cost to repair or replace damaged property with like kind and quality, without deducting depreciation.","inDefinedTermSet":{"@id":"https://virginiainsuranceappraiser.com/claim-and-policy-terms/#definedtermset"}},{"@type":"DefinedTerm","name":"Scope of loss","description":"The list of damaged items and the work needed to repair them.","inDefinedTermSet":{"@id":"https://virginiainsuranceappraiser.com/claim-and-policy-terms/#definedtermset"}},{"@type":"DefinedTerm","name":"Square","description":"A roofing unit equal to 100 square feet of roof surface.","inDefinedTermSet":{"@id":"https://virginiainsuranceappraiser.com/claim-and-policy-terms/#definedtermset"}},{"@type":"DefinedTerm","name":"Steep charge","description":"Extra labor added to an estimate for roofs too steep to walk safely, often 7/12 pitch and up.","inDefinedTermSet":{"@id":"https://virginiainsuranceappraiser.com/claim-and-policy-terms/#definedtermset"}},{"@type":"DefinedTerm","name":"Suit limitation","description":"The policy deadline for filing a lawsuit against the insurer, commonly two years in Virginia.","inDefinedTermSet":{"@id":"https://virginiainsuranceappraiser.com/claim-and-policy-terms/#definedtermset"}},{"@type":"DefinedTerm","name":"Supplement","description":"A request for additional payment for items missing from or underpriced in the original estimate.","inDefinedTermSet":{"@id":"https://virginiainsuranceappraiser.com/claim-and-policy-terms/#definedtermset"}},{"@type":"DefinedTerm","name":"Umpire","description":"The neutral third member of an appraisal panel who decides items the two appraisers can’t settle.","inDefinedTermSet":{"@id":"https://virginiainsuranceappraiser.com/claim-and-policy-terms/#definedtermset"}},{"@type":"DefinedTerm","name":"VPIA","description":"The Virginia Property Insurance Association, Virginia’s FAIR Plan.","inDefinedTermSet":{"@id":"https://virginiainsuranceappraiser.com/claim-and-policy-terms/#definedtermset"}},{"@type":"DefinedTerm","name":"Xactimate","description":"Estimating software widely used by insurers and contractors to price repairs by region.","inDefinedTermSet":{"@id":"https://virginiainsuranceappraiser.com/claim-and-policy-terms/#definedtermset"}}],"@id":"https://virginiainsuranceappraiser.com/claim-and-policy-terms/#definedtermset"},{"@type":"BreadcrumbList","itemListElement":[{"@type":"ListItem","position":1,"name":"Home","item":"https://virginiainsuranceappraiser.com/"},{"@type":"ListItem","position":2,"name":"Claim & policy terms","item":"https://virginiainsuranceappraiser.com/claim-and-policy-terms/"}],"@id":"https://virginiainsuranceappraiser.com/claim-and-policy-terms/#breadcrumb"}]}</script>
